  "it.w_capgain": "Capital gains other than the small listed-share limit need ITR-2 or ITR-3.",
  "it.w_houses": "More than two house properties rules out ITR-1 and ITR-4.",
  "it.w_foreign": "Foreign assets or foreign income need ITR-2 or ITR-3.",
  "it.w_director": "A director of a company cannot use ITR-1 or ITR-4.",
  "it.w_unlisted": "Holding unlisted shares rules out ITR-1 and ITR-4.",
  "it.w_agri": "Agricultural income above ₹5,000 rules out ITR-1 and ITR-4.",
  "it.w_loss": "Losses to carry forward or set off need ITR-2 or ITR-3.",
  "it.w_esop": "Deferred tax on employer shares needs ITR-2 or ITR-3.",
  "it.w_crypto": "Income from virtual digital assets needs ITR-2 or ITR-3.",
  "it.w_huf": "ITR-1 is only for individuals; a HUF without business income files ITR-2.",
  "it.w_pres2": "Your other answers rule out ITR-4, so the business income goes in ITR-3.",
  "it.w_pres": "Presumptive business income with simple other income fits ITR-4.",
  "it.w_simple": "Salary, house property and interest only, within the limits, fits ITR-1.",
  "it.n_forms": "The conditions follow the returns notified for the year ended 31 March 2026 (as reported by tax portals, ITR-1 and ITR-4 now allow up to two house properties). The returns for tax year 2026-27 are still to be notified under the Income-tax Rules, 2026: read the form's own list of who cannot use it before you file.",
  "it.n_ltcg": "Small long-term gains on listed shares or equity funds were allowed in ITR-1 and ITR-4 in some years; this has not been confirmed for 2026-27, so ITR-2 is the safe choice and the form's own list decides.",
  "it.n_ae": "Section 44AE (goods carriage) has its own conditions; check them before using the presumptive form.",
  "it.n_tax": "Declaring less profit than the presumptive rate needs books and may need an audit: then the return is ITR-3.",
