  /* Accountant hand-over (gap round 2026-11-14) */
  "nav.ca": "Accountant viewer",
  "ca.mk": "Make a file for my accountant (read-only)",
  "ca.t": "File for my accountant",
  "ca.intro": "Packs one business and period into ONE read-only file (.nsca). Send it to your accountant by WhatsApp or email. They open it on ca.niveshsahayak.in, read the books, add queries and send comments back to you.",
  "ca.notlive": "This is a file hand-over, not a live shared login. Your accountant sees the books as they were when you made the file. A live login would need a server that stores your books, and Nivesh Sahayak has none: your books stay on your device. For newer entries, make a new file.",
  "ca.what": "What goes in",
  "ca.earlier": "Entries before the first date too (needed for opening balances and ageing)",
  "ca.items": "Item list with purchase and sale rates (needed for stock)",
  "ca.extra": "Only if you tick it",
  "ca.extrah": "Left out unless you tick. Pictures (logo, signature), your PIN and the backup settings are never included.",
  "ca.orders": "Quotations, proforma invoices, sales orders, challans and purchase orders",
  "ca.staff": "Salary slips, staff advances, loans and EMIs, petty cash, and the employee list",
  "ca.phones": "Phone numbers, e-mail addresses and WhatsApp numbers of parties",
  "ca.bank": "Your own bank account number, IFSC and UPI id",
  "ca.no.orders": "quotations and orders",
  "ca.no.staff": "salary and staff records",
  "ca.no.phones": "phone numbers and e-mail addresses",
  "ca.no.bank": "your bank account details",
  "ca.note": "A note for your accountant (optional)",
  "ca.go": "Make the file",
  "ca.ready": "File ready: {n} entries, {p} parties, about {kb} KB.",
  "ca.code": "Check code:",
  "ca.codeh": "Send this code in your message, or read it out on a call. Your accountant compares it with the code the file shows, so a file changed on the way is noticed.",
  "ca.notin": "Not in this file: {w}.",
  "ca.nothing": "nothing was left out",
  "ca.copymsg": "Copy the message",
  "ca.copied": "Message copied",
  "ca.msgl": "Message to send with the file",
  "ca.msg": "Books of {biz} from {from} to {to}. Open the attached file on {url} (works without login, nothing is uploaded). Check code: {code}. This is a read-only copy made today; please send your queries back as a comments file.",
  "ca.how": "Send the file by WhatsApp or e-mail as an attachment. If WhatsApp shows the name with .nsca at the end, do not rename it.",
  "ca.cT": "CA comments",
  "ca.cIntro": "Your accountant sends back a small file of queries and comments (.nsca-comments). Load it here to see each query beside the entry it is about. Reply, mark it closed, and save the file again to send it back.",
  "ca.load": "Load comments file",
  "ca.export": "Save file with my replies",
  "ca.loaded": "{a} new, {c} updated",
  "ca.unsealed": "This file has no checksum, so a change on the way would not show.",
  "ca.badfile": "This is not a comments file from the accountant viewer, or it was changed.",
  "ca.openn": "{n} open",
  "ca.knote": "Comment",
  "ca.kquery": "Query",
  "ca.acct": "Accountant",
  "ca.yourreply": "Your reply:",
  "ca.closed": "Closed.",
  "ca.replyph": "Your reply to the accountant",
  "ca.savereply": "Save reply",
  "ca.markclosed": "Mark closed",
  "ca.saved": "Saved",
  "ca.none": "No queries or comments yet.",
  "ca.open": "Open",
  "ca.gone": "(no longer in your books)",
  "ca.party": "Party",
  "ca.screen": "Screen",
  "ca.general": "General comment",
  "cv.h1": "Accountant viewer: open the books file your client sent",
  "cv.intro": "Your client packs their books for a period into one file and sends it to you on WhatsApp or by email. Open it here and read it: dues, parties, ledgers, day book, GST working, final accounts and every document. Search and filter, ask queries on any entry, and send your comments back as a small file. Free, no login, and nothing is uploaded: the file is read inside your browser.",
  "cv.drop": "Drop the .nsca file here",
  "cv.choose": "Choose the file",
  "cv.dropnote": "The file stays on this device. Nothing is saved here and you cannot change your client's books from here.",
  "cv.nav.home": "Overview",
  "cv.docs": "Documents",
  "cv.day": "Day book",
  "cv.fin": "Final accounts",
  "cv.gst": "GST working",
  "cv.cT": "Queries and comments",
  "cv.how.h": "How this works",
  "cv.how.1": "Your client opens Nivesh Sahayak, goes to My data, Send to your accountant, and chooses \"Make a file for my accountant\" for one business and period.",
  "cv.how.2": "They send you the file (ending .nsca) and a short check code in the same message.",
  "cv.how.3": "You open the file on this page. The page tells you whether the file is unchanged and lets you type the check code your client gave you to compare.",
  "cv.how.4": "Read the books, search, and press \"Add a query or comment\" on any document, day-book entry or screen. Everything you write stays in this browser.",
  "cv.how.5": "When you are done, open \"Queries and comments\" and send the small .nsca-comments file back. Your client loads it and sees each query beside the entry. They can reply, and you can load the replies here.",
  "cv.live.h": "A file hand-over, not a live login",
  "cv.live.p": "This is a file hand-over. You do not log in to your client's account and you do not see changes they make later. A live shared login would need a server that stores the books, and Nivesh Sahayak has none: the books stay on your client's device. For a newer period or after corrections, ask your client for a fresh file.",
  "cv.safe.h": "What is in the file, and what is not",
  "cv.safe.p": "Your client ticks what goes in. By default the file has the entries, parties and items of one business up to the end of the period. Quotations and orders, salary and staff records, phone numbers and e-mail addresses, and the business's bank account details are left out unless your client ticks them. Pictures, the PIN and the backup settings are never included. The file carries a checksum so any change to it shows on this page. The checksum cannot stop someone who edits the file and recalculates it, so compare the check code with the one your client sent separately.",
  "cv.readonly": "This is a read-only view of a file: nothing can be changed or saved here.",
