  "pr.pfintro": "ᱪᱟᱸᱫᱚ ᱨᱮᱭᱟᱜ ᱥᱮᱞᱟᱨᱤ ᱥᱞᱤᱯ ᱠᱷᱚᱱ EPFO unified portal ᱞᱟᱹᱜᱤᱫ ECR ᱴᱮᱠᱥᱴ ᱯᱷᱟᱭᱤᱞ ᱟᱨ ᱪᱟᱞᱟᱱ ᱴᱟᱠᱟ ᱛᱮᱭᱟᱨᱚᱜᱼᱟ᱾ ᱯᱩᱭᱞᱩ ᱥᱞᱤᱯ ᱛᱮᱭᱟᱨ ᱢᱮ (ᱥᱮᱞᱟᱨᱤ ᱴᱮᱵᱽ); ᱥᱞᱤᱯ ᱵᱟᱹᱱᱩᱜ ᱠᱟᱹᱢᱤᱭᱟᱹ ᱞᱟᱛᱟᱨ ᱨᱮ ᱞᱤᱥᱴ ᱢᱮᱱᱟᱜ ᱠᱚᱣᱟ᱾",
  "pr.unver_pf": "ᱟᱯᱞᱳᱰ ᱞᱟᱦᱟ ᱧᱮᱞ ᱢᱮ: ᱱᱚᱶᱟ ᱛᱮᱭᱟᱨ ᱚᱠᱛᱚ (14 Nov 2026) EPFO ᱨᱮᱭᱟᱜ ᱯᱷᱟᱭᱤᱞ ᱥᱴᱨᱟᱠᱪᱟᱨ ᱰᱚᱠᱭᱩᱢᱮᱱᱴ ᱵᱟᱝ ᱡᱷᱤᱡ ᱜᱟᱱ ᱞᱮᱱᱟ᱾ 11 ᱯᱷᱤᱞᱰ ᱟᱨ ᱚᱱᱟ ᱨᱮᱭᱟᱜ ᱛᱷᱟᱨ ᱫᱚ ᱯᱮᱨᱚᱞ ᱥᱚᱯᱷᱴᱣᱮᱭᱟᱨ ᱛᱮᱭᱟᱨᱤᱭᱟᱹ ᱠᱚ ᱡᱟᱦᱟᱸ ᱩᱫᱩᱜ ᱟᱠᱟᱫᱟ ᱚᱱᱟ ᱞᱮᱠᱟ ᱠᱟᱱᱟ᱾ ᱯᱷᱟᱭᱤᱞ EPFO ᱯᱚᱨᱴᱟᱞ ᱨᱮᱭᱟᱜ ECR ᱥᱟᱦᱴᱟ ᱨᱮ ᱟᱯᱞᱳᱰ ᱢᱮ; ᱯᱚᱨᱴᱟᱞ ᱢᱤᱫ ᱞᱟᱭᱤᱱ ᱵᱟᱝ ᱦᱟᱛᱟᱣ ᱠᱷᱟᱱ ᱠᱟᱨᱚᱬ ᱮ ᱞᱟᱹᱭᱟ᱾",
