  "pr.unver_esi": "ᱱᱚᱶᱟ ᱥᱤᱴ ᱫᱚ ESIC ᱯᱚᱨᱴᱟᱞ ᱨᱮᱭᱟᱜ ᱟᱡᱟᱜ Monthly Contribution ᱴᱮᱢᱯᱞᱮᱴ ᱞᱮᱠᱟ (15 Nov 2026 ᱧᱮᱞ ᱟᱠᱟᱱ): ᱛᱩᱨᱩᱭ ᱴᱮᱠᱥᱴ ᱠᱟᱞᱚᱢ, Excel 97-2003 (.xls) ᱞᱮᱠᱟ ᱥᱮᱣ᱾ ᱱᱚᱶᱟ ᱪᱟᱸᱫᱚ ᱫᱚᱨᱢᱟᱦᱟ ᱵᱟᱹᱱᱩᱜ ᱠᱟᱹᱢᱤᱭᱟᱹ ᱦᱚᱸ ᱠᱟᱨᱚᱬ ᱠᱳᱰ ᱥᱟᱶ ᱢᱮᱱᱟᱜ ᱠᱚᱣᱟ᱾ ᱯᱩᱭᱞᱩ ᱢᱤᱫ ᱪᱟᱸᱫᱚ ᱟᱯᱞᱳᱰ ᱠᱟᱛᱮ ᱯᱚᱨᱴᱟᱞ ᱨᱮᱭᱟᱜ ᱞᱟᱛᱟᱨ ᱧᱮᱞ ᱢᱮ᱾",
