  "it.f_dedo": "ᱢᱟᱨᱮ ᱨᱤᱡᱤᱢ: ᱮᱴᱟᱜ ᱰᱤᱰᱟᱠᱥᱚᱱ",
  "it.f_dedo_h": "ᱦᱮᱞᱛᱷ ᱤᱱᱥᱩᱨᱮᱱᱥ, ᱟᱡᱟᱜ ᱛᱟᱦᱮᱸ ᱚᱲᱟᱜ ᱨᱮᱭᱟᱜ ᱦᱚᱢ ᱞᱚᱱ ᱥᱩᱫ, NPS ᱵᱟᱹᱲᱛᱤ ᱟᱨ ᱚᱱᱟ ᱞᱮᱠᱟᱱ, ᱟᱢ ᱡᱚᱲ ᱟᱠᱟᱫ᱾",
  "it.f_nps": "ᱢᱟᱞᱤᱠ ᱨᱮᱭᱟᱜ NPS ᱦᱟᱹᱴᱤᱧ",
  "it.f_nps_h": "ᱵᱟᱨᱭᱟ ᱨᱤᱡᱤᱢ ᱨᱮ ᱢᱟᱱᱟᱣ; ᱴᱟᱠᱟ ᱚᱞ ᱢᱮ᱾",
  "it.f_sur": "ᱥᱚᱨᱪᱟᱨᱡ",
  "it.f_sur_h": "ᱵᱟᱝ ᱦᱤᱥᱟᱵ ᱦᱩᱭᱩᱜᱼᱟ᱾ ᱟᱢᱟᱜ ᱟᱹᱢᱫᱟᱹᱱᱤ ₹50 ᱞᱟᱠᱷ ᱪᱮᱛᱟᱱ ᱛᱟᱦᱮᱸ ᱠᱷᱟᱱ ᱴᱟᱠᱟ ᱚᱞ ᱢᱮ᱾",
  "it.f_tds": "ᱱᱚᱶᱟ ᱟᱹᱢᱫᱟᱹᱱᱤ ᱨᱮ ᱠᱟᱴᱟᱣ ᱟᱠᱟᱱ TDS ᱟᱨ TCS",
  "it.f_tds_h": "ᱥᱮᱨᱢᱟ ᱨᱮᱭᱟᱜ ᱟᱢᱟᱜ ᱨᱚᱥᱤᱫ ᱟᱨ ᱮᱴᱟᱜ ᱟᱹᱢᱫᱟᱹᱱᱤ ᱨᱮ ᱚᱞ TDS ᱠᱷᱚᱱ ᱮᱦᱚᱵᱚᱜᱼᱟ᱾ ᱱᱤᱛ ᱦᱚᱸ ᱠᱟᱴᱟᱣ ᱞᱟᱹᱜᱤᱫ ᱵᱟᱠᱤ ᱥᱮᱞᱮᱫ ᱢᱮ᱾",
  "it.f_def": "ᱛᱟᱭᱚᱢ ᱦᱮᱡᱚᱜ ᱜᱮᱱ ᱥᱮ ᱞᱟᱵᱷ ᱨᱮ ᱴᱮᱠᱥ",
  "it.f_def_h": "ᱠᱮᱯᱤᱴᱟᱞ ᱜᱮᱱ, ᱡᱤᱛᱟᱹᱣ, ᱰᱤᱵᱷᱤᱰᱮᱱᱰ ᱥᱮ ᱯᱩᱭᱞᱩ ᱥᱮᱨᱢᱟ ᱵᱤᱡᱱᱮᱥ ᱞᱟᱵᱷ ᱡᱟᱦᱟᱸ ᱱᱤᱛ ᱦᱟᱹᱵᱤᱡ ᱵᱟᱝ ᱧᱟᱢ ᱟᱠᱟᱫᱟ: ᱵᱟᱠᱤ ᱠᱤᱥᱛᱤ ᱨᱮ ᱮᱢ ᱠᱷᱟᱱ ᱞᱟᱦᱟ ᱠᱤᱥᱛᱤ ᱞᱟᱹᱜᱤᱫ ᱵᱟᱝ ᱞᱮᱠᱷᱟᱭᱚᱜᱼᱟ (section 425(4))᱾",
  "it.f_mon": "ᱴᱮᱠᱥ ᱠᱚᱢ ᱠᱷᱟᱱ ᱥᱩᱫ ᱨᱮᱭᱟᱜ ᱪᱟᱸᱫᱚ",
  "it.f_mon_h": "ᱥᱮᱨᱢᱟ ᱛᱟᱭᱚᱢ 1 April ᱠᱷᱚᱱ ᱨᱤᱴᱚᱨᱱ ᱯᱨᱚᱥᱮᱥ ᱫᱤᱱ ᱦᱟᱹᱵᱤᱡ᱾ 4 = 31 July ᱦᱟᱹᱵᱤᱡ ᱨᱤᱴᱚᱨᱱ ᱯᱷᱟᱭᱤᱞ᱾",
  "it.m_senior": "60 ᱥᱮ ᱵᱟᱹᱲᱛᱤ ᱩᱢᱮᱨ ᱨᱮᱱᱟᱜ ᱛᱟᱦᱮᱸᱱᱤᱭᱟᱹ ᱡᱟᱦᱟᱸᱭ ᱴᱷᱮᱱ ᱵᱤᱡᱱᱮᱥ ᱥᱮ ᱯᱨᱚᱯᱷᱮᱥᱚᱱ ᱟᱹᱢᱫᱟᱹᱱᱤ ᱵᱟᱹᱱᱩᱜᱼᱟ, ᱚᱱᱟᱭ ᱫᱚ ᱮᱰᱵᱷᱟᱱᱥ ᱴᱮᱠᱥ ᱵᱟᱝ ᱮᱢᱟ (section 403(3))᱾ ᱨᱤᱴᱚᱨᱱ ᱯᱷᱟᱭᱤᱞ ᱚᱠᱛᱚ ᱵᱟᱠᱤ ᱮᱢ ᱢᱮ᱾",
  "it.m_below": "TDS ᱛᱟᱭᱚᱢ ᱴᱮᱠᱥ {n} ᱠᱟᱱᱟ, ₹10,000 ᱠᱷᱚᱱ ᱠᱚᱢ, ᱚᱱᱟᱛᱮ ᱮᱰᱵᱷᱟᱱᱥ ᱴᱮᱠᱥ ᱵᱟᱠᱤ ᱵᱟᱹᱱᱩᱜᱼᱟ (section 404)᱾ ᱨᱤᱴᱚᱨᱱ ᱯᱷᱟᱭᱤᱞ ᱚᱠᱛᱚ ᱵᱟᱠᱤ ᱮᱢ ᱢᱮ᱾",
  "it.m_pres": "ᱯᱨᱤᱡᱟᱢᱯᱴᱤᱵᱷ ᱥᱠᱤᱢ ᱨᱮ ᱥᱟᱱᱟᱢ ᱮᱰᱵᱷᱟᱱᱥ ᱴᱮᱠᱥ 15 March ᱥᱮ ᱞᱟᱦᱟ ᱮᱢᱚᱜᱼᱟ (section 408(2))᱾",
  "it.m_sur": "ᱟᱢᱟᱜ ᱟᱹᱢᱫᱟᱹᱱᱤ ₹50 ᱞᱟᱠᱷ ᱪᱮᱛᱟᱱ: ᱥᱚᱨᱪᱟᱨᱡ ᱚᱞ ᱢᱮ, ᱱᱚᱸᱰᱮ ᱵᱟᱝ ᱦᱤᱥᱟᱵᱚᱜᱼᱟ᱾",
  "it.m_past": "ᱱᱚᱶᱟ ᱥᱮᱨᱢᱟ ᱢᱩᱪᱟᱹᱫ ᱮᱱᱟ᱾ 31 March ᱛᱟᱭᱚᱢ ᱮᱢ ᱟᱠᱟᱱ ᱮᱰᱵᱷᱟᱱᱥ ᱴᱮᱠᱥ ᱫᱚ ᱱᱚᱶᱟ ᱥᱮᱨᱢᱟ ᱞᱟᱹᱜᱤᱫ ᱮᱰᱵᱷᱟᱱᱥ ᱴᱮᱠᱥ ᱞᱮᱠᱟ ᱵᱟᱝ ᱞᱮᱠᱷᱟᱭᱚᱜᱼᱟ; ᱞᱟᱛᱟᱨ ᱨᱮᱱᱟᱜ ᱥᱩᱫ ᱫᱚ ᱠᱚᱢ ᱮᱢ ᱨᱮᱭᱟᱜ ᱫᱟᱢ ᱩᱫᱩᱜᱟ᱾",
  "it.m_season": "ᱟᱱᱫᱟᱡᱽ ᱫᱚ ᱱᱤᱛ ᱦᱟᱹᱵᱤᱡ ᱨᱮᱭᱟᱜ ᱞᱟᱵᱷ ᱥᱚᱡᱮ ᱛᱮ ᱯᱩᱨᱟᱹ ᱥᱮᱨᱢᱟ ᱞᱟᱹᱜᱤᱫ ᱦᱤᱥᱟᱵᱟ᱾ ᱟᱢᱟᱜ ᱵᱤᱡᱱᱮᱥ ᱵᱚᱠᱛᱚ ᱞᱮᱠᱟ ᱛᱟᱦᱮᱸ ᱠᱷᱟᱱ ᱥᱮᱨᱢᱟ ᱞᱟᱹᱜᱤᱫ ᱟᱢᱟᱜ ᱮᱞ ᱚᱞ ᱢᱮ᱾",
