  "it.b1": "ᱨᱮᱴ ({d} ᱦᱟᱹᱵᱤᱡ), ᱴᱮᱠᱥ ᱥᱮᱨᱢᱟ 2026-27: ᱱᱟᱶᱟ ᱨᱤᱡᱤᱢ ₹4 ᱞᱟᱠᱷ ᱦᱟᱹᱵᱤᱡ ᱥᱩᱱ, ₹8 ᱞᱟᱠᱷ ᱦᱟᱹᱵᱤᱡ 5%, ₹12 ᱞᱟᱠᱷ ᱦᱟᱹᱵᱤᱡ 10%, ₹16 ᱞᱟᱠᱷ ᱦᱟᱹᱵᱤᱡ 15%, ₹20 ᱞᱟᱠᱷ ᱦᱟᱹᱵᱤᱡ 20%, ₹24 ᱞᱟᱠᱷ ᱦᱟᱹᱵᱤᱡ 25%, ᱪᱮᱛᱟᱱ 30%; ₹12 ᱞᱟᱠᱷ ᱦᱟᱹᱵᱤᱡ ᱟᱹᱢᱫᱟᱹᱱᱤ ᱨᱮ ᱴᱮᱠᱥ ᱵᱟᱹᱱᱩᱜ ᱞᱮᱠᱟ ᱨᱤᱵᱮᱴ, ᱚᱱᱟ ᱪᱮᱛᱟᱱ ᱢᱟᱨᱡᱤᱱᱟᱞ ᱨᱤᱞᱤᱯᱷ ᱥᱟᱶ; ᱥᱮᱞᱟᱨᱤ ᱨᱮ ₹75,000 ᱥᱴᱮᱱᱰᱟᱨᱰ ᱰᱤᱰᱟᱠᱥᱚᱱ᱾ ᱢᱟᱨᱮ ᱨᱤᱡᱤᱢ: ₹2.5 ᱞᱟᱠᱷ ᱦᱟᱹᱵᱤᱡ ᱥᱩᱱ (60 ᱨᱮ ₹3 ᱞᱟᱠᱷ, 80 ᱨᱮ ₹5 ᱞᱟᱠᱷ), ₹5 ᱞᱟᱠᱷ ᱦᱟᱹᱵᱤᱡ 5%, ₹10 ᱞᱟᱠᱷ ᱦᱟᱹᱵᱤᱡ 20%, ᱪᱮᱛᱟᱱ 30%; ₹5 ᱞᱟᱠᱷ ᱦᱟᱹᱵᱤᱡ ₹12,500 ᱨᱤᱵᱮᱴ; ₹50,000 ᱥᱴᱮᱱᱰᱟᱨᱰ ᱰᱤᱰᱟᱠᱥᱚᱱ᱾ ᱱᱚᱶᱟ ᱨᱮᱴ ᱫᱚ ᱥᱮᱞᱟᱨᱤ ᱥᱞᱤᱯ ᱴᱩᱞ ᱞᱟᱦᱟ ᱠᱷᱚᱱ ᱵᱮᱵᱷᱟᱨ ᱮᱫᱟ; ᱱᱚᱶᱟ ᱵᱤᱞᱰ ᱨᱮ Finance Act ᱠᱷᱚᱱ ᱫᱩᱦᱲᱟᱹ ᱵᱟᱝ ᱯᱟᱲᱦᱟᱣ ᱞᱮᱱᱟ, ᱚᱱᱟᱛᱮ ᱧᱮᱞ ᱢᱮ᱾",
  "it.b2": "ᱮᱰᱵᱷᱟᱱᱥ ᱴᱮᱠᱥ (Income-tax Act 2025, sections 403 ᱠᱷᱚᱱ 408): TDS ᱛᱟᱭᱚᱢ ᱴᱮᱠᱥ ₹10,000 ᱥᱮ ᱵᱟᱹᱲᱛᱤ ᱠᱷᱟᱱ ᱮᱢ ᱞᱟᱹᱠᱛᱤ; 15 June ᱦᱟᱹᱵᱤᱡ 15%, 15 September ᱦᱟᱹᱵᱤᱡ 45%, 15 December ᱦᱟᱹᱵᱤᱡ 75%, 15 March ᱦᱟᱹᱵᱤᱡ ᱡᱚᱛᱚ; ᱯᱨᱤᱡᱟᱢᱯᱴᱤᱵᱷ ᱴᱮᱠᱥ ᱮᱢᱤᱭᱟᱹ 15 March ᱦᱟᱹᱵᱤᱡ ᱡᱚᱛᱚ ᱮ ᱮᱢᱟ; 31 March ᱦᱟᱹᱵᱤᱡ ᱯᱮᱢᱮᱱᱴ ᱥᱮᱨᱢᱟ ᱞᱟᱹᱜᱤᱫ ᱞᱮᱠᱷᱟᱭᱚᱜᱼᱟ; ᱵᱤᱡᱱᱮᱥ ᱟᱹᱢᱫᱟᱹᱱᱤ ᱵᱟᱹᱱᱩᱜ 60 ᱥᱮ ᱵᱟᱹᱲᱛᱤ ᱩᱢᱮᱨ ᱨᱮᱱᱟᱜ ᱛᱟᱦᱮᱸᱱᱤᱭᱟᱹ ᱪᱷᱩᱴ᱾",
  "it.b3": "ᱥᱩᱫ: section 424 (ᱢᱟᱨᱮ 234B) ᱫᱚ ᱴᱮᱠᱥ ᱨᱮᱭᱟᱜ 90% ᱠᱷᱚᱱ ᱠᱚᱢ ᱮᱢ ᱠᱷᱟᱱ ᱠᱚᱢ ᱴᱟᱠᱟ ᱨᱮ ᱯᱨᱚᱛᱤ ᱪᱟᱸᱫᱚ ᱥᱮ ᱪᱟᱸᱫᱚ ᱦᱟᱹᱴᱤᱧ ᱨᱮ 1%; section 425 (ᱢᱟᱨᱮ 234C) ᱫᱚ ᱯᱩᱭᱞᱩ ᱯᱮ ᱠᱤᱥᱛᱤ ᱨᱮᱭᱟᱜ ᱠᱚᱢ ᱴᱟᱠᱟ ᱨᱮ 3% (15 June ᱦᱟᱹᱵᱤᱡ 12% ᱟᱨ 15 September ᱦᱟᱹᱵᱤᱡ 36% ᱮᱢ ᱠᱷᱟᱱ ᱵᱟᱹᱱᱩᱜᱼᱟ) ᱟᱨ March ᱨᱮᱭᱟᱜ ᱠᱚᱢ ᱴᱟᱠᱟ ᱨᱮ 1%᱾",
  "it.b4": "ᱪᱮᱛᱟᱱ ᱨᱮᱱᱟᱜ section ᱠᱚ 15 Nov 2026 ᱨᱮ Income Tax Department ᱨᱮᱭᱟᱜ ᱣᱮᱵᱥᱟᱭᱤᱴ (incometaxindia.gov.in) ᱨᱮᱭᱟᱜ ᱥᱚᱨᱠᱟᱨᱤ ᱚᱞ ᱥᱟᱶ ᱟᱹᱲᱟᱹ ᱟᱹᱲᱟᱹ ᱧᱮᱞ ᱟᱠᱟᱱᱟ᱾ ᱪᱷᱟᱯᱟ Act ᱜᱮ ᱢᱟᱱᱟᱣᱜᱼᱟ᱾",
  "it.b5": "ᱠᱷᱟᱛᱟ ᱞᱟᱵᱷ ᱫᱚ ᱴᱮᱠᱥ ᱞᱟᱜᱟᱣ ᱞᱟᱵᱷ ᱵᱟᱝ ᱠᱟᱱᱟ: Act ᱞᱮᱠᱟ ᱰᱮᱯᱨᱤᱥᱤᱭᱮᱥᱚᱱ, ᱵᱟᱝ ᱢᱟᱱᱟᱣ ᱠᱷᱚᱨᱚᱪ ᱟᱨ ᱯᱨᱤᱡᱟᱢᱯᱴᱤᱵᱷ ᱱᱤᱭᱚᱢ ᱚᱱᱟ ᱵᱚᱫᱚᱞᱟ᱾ ᱱᱚᱶᱟ ᱯᱞᱟᱱ ᱟᱨ ᱰᱮᱴᱟ ᱥᱤᱴ ᱟᱢᱟᱜ ᱮᱠᱟᱣᱩᱱᱴᱮᱱᱴ ᱴᱷᱮᱱ ᱮᱢ ᱢᱮ᱾",
  "it.b6": "ᱵᱟᱝ ᱦᱤᱥᱟᱵ ᱦᱩᱭᱩᱜᱼᱟ: ᱥᱚᱨᱪᱟᱨᱡ, ᱵᱤᱥᱮᱥ ᱨᱮᱴ ᱨᱮ ᱠᱮᱯᱤᱴᱟᱞ ᱜᱮᱱ, ᱵᱤᱫᱮᱥᱤ ᱴᱮᱠᱥ ᱨᱤᱞᱤᱯᱷ, ᱜᱤᱫᱽᱨᱤ ᱨᱮᱭᱟᱜ ᱟᱹᱢᱫᱟᱹᱱᱤ ᱨᱮ ᱴᱮᱠᱥ, ᱟᱨ ᱫᱮᱨᱤ ᱯᱷᱟᱭᱤᱞ ᱨᱮᱭᱟᱜ ᱥᱩᱫ᱾",
  "it.b7": "ᱪᱮᱫ ᱦᱚᱸ ᱯᱷᱟᱭᱤᱞ ᱵᱟᱝ ᱦᱩᱭᱩᱜᱼᱟ ᱟᱨ ᱟᱢᱟᱜ ᱠᱷᱟᱛᱟ ᱨᱮ ᱪᱮᱫ ᱦᱚᱸ ᱵᱟᱝ ᱚᱞᱚᱜᱼᱟ᱾",
  "it.itr_h": "ᱚᱠᱟ ᱨᱤᱴᱚᱨᱱ ᱯᱷᱚᱨᱢ ᱵᱮᱵᱷᱟᱨᱚᱜᱼᱟ, ᱪᱮᱫᱟᱜ, ᱟᱨ ᱚᱠᱟ ᱠᱟᱜᱚᱡ ᱛᱮᱭᱟᱨ ᱫᱚᱦᱚ ᱞᱟᱹᱜᱤᱫ ᱥᱟᱵ ᱥᱟᱵ ᱠᱩᱠᱞᱤ ᱨᱮᱭᱟᱜ ᱛᱮᱞᱟ ᱮᱢ ᱢᱮ᱾",
