  "it.q_loss": "ᱤᱧᱴᱷᱮᱱ ᱟᱜᱟᱢ ᱤᱫᱤ ᱥᱮ ᱥᱮᱴ ᱚᱯᱷ ᱞᱟᱹᱜᱤᱫ ᱦᱟᱹᱱᱤ ᱢᱮᱱᱟᱜᱼᱟ",
  "it.q_esop": "ᱤᱧᱟᱜ ᱢᱟᱞᱤᱠ ᱠᱷᱚᱱ ᱥᱮᱭᱟᱨ ᱨᱮ ᱫᱮᱨᱤ ᱴᱮᱠᱥ ᱢᱮᱱᱟᱜᱼᱟ (ESOP)",
  "it.q_crypto": "ᱤᱧ ᱠᱨᱤᱯᱴᱚ ᱞᱮᱠᱟᱱ ᱵᱷᱟᱨᱪᱩᱭᱟᱞ ᱰᱤᱡᱤᱴᱟᱞ ᱡᱟᱭᱫᱟᱫ ᱟᱠᱷᱨᱤᱧ ᱟᱠᱟᱫᱟᱧ",
  "it.formd_ITR-1": "ᱥᱮᱞᱟᱨᱤ ᱥᱮ ᱯᱮᱱᱥᱚᱱ, ᱵᱟᱨ ᱦᱟᱹᱵᱤᱡ ᱚᱲᱟᱜ ᱡᱟᱭᱫᱟᱫ ᱟᱨ ᱥᱩᱫ ᱞᱮᱠᱟᱱ ᱮᱴᱟᱜ ᱥᱚᱨᱥ, ᱟᱨ ₹50 ᱞᱟᱠᱷ ᱦᱟᱹᱵᱤᱡ ᱡᱚᱛᱚ ᱟᱹᱢᱫᱟᱹᱱᱤ ᱢᱮᱱᱟᱜ ᱛᱟᱦᱮᱸᱱᱤᱭᱟᱹ ᱦᱚᱲ ᱞᱟᱹᱜᱤᱫ᱾",
  "it.formd_ITR-2": "ᱵᱤᱡᱱᱮᱥ ᱥᱮ ᱯᱨᱚᱯᱷᱮᱥᱚᱱ ᱟᱹᱢᱫᱟᱹᱱᱤ ᱵᱟᱹᱱᱩᱜ ᱦᱚᱲ ᱥᱮ HUF ᱞᱟᱹᱜᱤᱫ ᱡᱟᱦᱟᱸᱭ ᱴᱷᱮᱱ ᱠᱮᱯᱤᱴᱟᱞ ᱜᱮᱱ, ₹50 ᱞᱟᱠᱷ ᱪᱮᱛᱟᱱ ᱟᱹᱢᱫᱟᱹᱱᱤ, ᱵᱟᱨ ᱠᱷᱚᱱ ᱵᱟᱹᱲᱛᱤ ᱚᱲᱟᱜ ᱡᱟᱭᱫᱟᱫ, ᱵᱤᱫᱮᱥᱤ ᱡᱟᱭᱫᱟᱫ ᱥᱮ ᱟᱹᱢᱫᱟᱹᱱᱤ ᱢᱮᱱᱟᱜᱼᱟ, ᱥᱮ ITR-1 ᱨᱮ ᱵᱟᱝ ᱦᱟᱛᱟᱣ ᱠᱟᱱᱟ᱾",
  "it.formd_ITR-3": "ᱯᱨᱤᱡᱟᱢᱯᱴᱤᱵᱷ ᱥᱠᱤᱢ ᱵᱟᱝ ᱵᱤᱡᱱᱮᱥ ᱥᱮ ᱯᱨᱚᱯᱷᱮᱥᱚᱱ ᱟᱹᱢᱫᱟᱹᱱᱤ ᱢᱮᱱᱟᱜ ᱦᱚᱲ ᱥᱮ HUF, ᱯᱷᱟᱨᱢ ᱨᱮᱭᱟᱜ ᱯᱟᱨᱴᱱᱟᱨ, ᱥᱮ ITR-4 ᱨᱮ ᱵᱟᱝ ᱦᱟᱛᱟᱣ ᱡᱟᱦᱟᱸᱭ ᱞᱟᱹᱜᱤᱫ᱾",
  "it.formd_ITR-4": "ᱯᱨᱤᱡᱟᱢᱯᱴᱤᱵᱷ ᱵᱤᱡᱱᱮᱥ ᱟᱹᱢᱫᱟᱹᱱᱤ, ₹50 ᱞᱟᱠᱷ ᱦᱟᱹᱵᱤᱡ ᱡᱚᱛᱚ ᱟᱹᱢᱫᱟᱹᱱᱤ, ᱥᱮᱞᱟᱨᱤ ᱥᱮ ᱯᱮᱱᱥᱚᱱ, ᱵᱟᱨ ᱦᱟᱹᱵᱤᱡ ᱚᱲᱟᱜ ᱡᱟᱭᱫᱟᱫ ᱟᱨ ᱮᱴᱟᱜ ᱥᱚᱨᱥ ᱢᱮᱱᱟᱜ ᱛᱟᱦᱮᱸᱱᱤᱭᱟᱹ ᱦᱚᱲ ᱥᱮ HUF ᱞᱟᱹᱜᱤᱫ᱾",
  "it.formd_ITR-5": "ᱯᱷᱟᱨᱢ, LLP, ᱦᱚᱲ ᱜᱟᱶᱛᱟ ᱟᱨ ᱦᱚᱲ ᱥᱟᱸᱜᱷᱟ ᱞᱟᱹᱜᱤᱫ᱾",
