  "nav.ca": "ᱮᱠᱟᱣᱩᱱᱴᱮᱱᱴ ᱵᱷᱤᱣᱟᱨ",
  "ca.mk": "ᱤᱧᱟᱜ ᱮᱠᱟᱣᱩᱱᱴᱮᱱᱴ ᱞᱟᱹᱜᱤᱫ ᱯᱷᱟᱭᱤᱞ ᱛᱮᱭᱟᱨ ᱢᱮ (ᱮᱠᱮᱱ ᱯᱟᱲᱦᱟᱣ)",
  "ca.t": "ᱤᱧᱟᱜ ᱮᱠᱟᱣᱩᱱᱴᱮᱱᱴ ᱞᱟᱹᱜᱤᱫ ᱯᱷᱟᱭᱤᱞ",
  "ca.intro": "ᱢᱤᱫ ᱵᱤᱡᱱᱮᱥ ᱟᱨ ᱚᱠᱛᱚ ᱢᱤᱫ ᱮᱠᱮᱱ ᱯᱟᱲᱦᱟᱣ ᱯᱷᱟᱭᱤᱞ (.nsca) ᱨᱮ ᱵᱟᱸᱫᱷᱟᱣᱜᱼᱟ᱾ WhatsApp ᱥᱮ ᱤᱢᱮᱞ ᱛᱮ ᱟᱢᱟᱜ ᱮᱠᱟᱣᱩᱱᱴᱮᱱᱴ ᱴᱷᱮᱱ ᱠᱩᱞ ᱢᱮ᱾ ᱩᱱᱤ ᱫᱚ ca.niveshsahayak.in ᱨᱮ ᱡᱷᱤᱡ ᱠᱟᱛᱮ ᱠᱷᱟᱛᱟ ᱯᱟᱲᱦᱟᱣ, ᱠᱩᱠᱞᱤ ᱥᱮᱞᱮᱫ ᱟᱨ ᱢᱚᱱᱛᱚ ᱟᱢ ᱴᱷᱮᱱ ᱨᱩᱣᱟᱹᱲ ᱠᱩᱞᱟᱭ᱾",
  "ca.notlive": "ᱱᱚᱶᱟ ᱫᱚ ᱯᱷᱟᱭᱤᱞ ᱮᱢ ᱠᱟᱱᱟ, ᱞᱟᱭᱤᱵᱷ ᱥᱮᱭᱟᱨ ᱞᱚᱜᱤᱱ ᱵᱟᱝ᱾ ᱯᱷᱟᱭᱤᱞ ᱛᱮᱭᱟᱨ ᱚᱠᱛᱚ ᱠᱷᱟᱛᱟ ᱡᱮᱞᱮᱠᱟ ᱛᱟᱦᱮᱸ ᱠᱟᱱᱟ ᱚᱱᱠᱟ ᱜᱮ ᱟᱢᱟᱜ ᱮᱠᱟᱣᱩᱱᱴᱮᱱᱴ ᱮ ᱧᱮᱞᱟ᱾ ᱞᱟᱭᱤᱵᱷ ᱞᱚᱜᱤᱱ ᱞᱟᱹᱜᱤᱫ ᱠᱷᱟᱛᱟ ᱫᱚᱦᱚ ᱥᱟᱨᱵᱷᱟᱨ ᱞᱟᱹᱠᱛᱤᱭᱟᱱᱟ, ᱟᱨ Nivesh Sahayak ᱴᱷᱮᱱ ᱵᱟᱹᱱᱩᱜᱼᱟ: ᱟᱢᱟᱜ ᱠᱷᱟᱛᱟ ᱟᱢᱟᱜ ᱰᱤᱵᱷᱟᱭᱤᱥ ᱨᱮ ᱜᱮ ᱛᱟᱦᱮᱸᱱᱟ᱾ ᱱᱟᱶᱟ ᱮᱱᱴᱨᱤ ᱞᱟᱹᱜᱤᱫ ᱱᱟᱶᱟ ᱯᱷᱟᱭᱤᱞ ᱛᱮᱭᱟᱨ ᱢᱮ᱾",
  "ca.what": "ᱪᱮᱫ ᱥᱮᱞᱮᱫᱚᱜᱼᱟ",
