  "hm.h.recv.how": "ᱜᱨᱟᱦᱟᱠ ᱠᱚ ᱴᱷᱮᱱ {r} ᱵᱟᱠᱤ᱾ ᱟᱢ ᱫᱤᱱ ᱨᱮ ᱯᱟᱥᱤ {d} ᱟᱠᱷᱨᱤᱧᱟᱢ, ᱚᱱᱟᱛᱮ ᱢᱤᱫ ᱵᱤᱞ ᱨᱩᱣᱟᱹᱲ ᱦᱮᱡ ᱞᱟᱹᱜᱤᱫ ᱯᱟᱥᱤ {n} ᱫᱤᱱ ᱞᱟᱜᱟᱣᱜᱼᱟ᱾",
  "hm.h.recv.good": "ᱴᱟᱠᱟ ᱞᱚᱜᱚᱱ ᱨᱩᱣᱟᱹᱲ ᱦᱮᱡᱚᱜᱼᱟ᱾ ᱫᱮᱨᱤ ᱦᱚᱲ ᱠᱚ ᱩᱭᱦᱟᱹᱨ ᱛᱟᱦᱮᱸᱱ ᱢᱮ᱾",
  "hm.h.recv.ok": "ᱴᱟᱠᱟ ᱫᱮᱨᱤ ᱛᱮ ᱨᱩᱣᱟᱹᱲ ᱦᱮᱡᱚᱜᱼᱟ᱾ ᱵᱟᱠᱤ ᱥᱠᱨᱤᱱ ᱠᱷᱚᱱ ᱡᱷᱚᱛᱚ ᱦᱟᱯᱛᱟ ᱩᱭᱦᱟᱹᱨ ᱠᱩᱞ ᱢᱮ᱾",
  "hm.h.recv.low": "ᱴᱟᱠᱟ ᱜᱨᱟᱦᱟᱠ ᱠᱚ ᱴᱷᱮᱱ ᱟᱹᱰᱤ ᱡᱟᱹᱥᱛᱤ ᱚᱠᱛᱚ ᱛᱟᱦᱮᱸᱱᱟ᱾ ᱯᱩᱭᱞᱩ ᱢᱟᱨᱮ ᱵᱤᱞ ᱦᱟᱛᱟᱣ ᱢᱮ ᱟᱨ ᱱᱟᱶᱟ ᱚᱨᱰᱟᱨ ᱞᱟᱦᱟ ᱦᱟᱹᱴᱤᱧ ᱯᱮᱢᱮᱱᱴ ᱠᱷᱚᱡ ᱢᱮ᱾",
  "hm.h.recv.rule": "ᱜᱨᱟᱦᱟᱠ ᱠᱚ ᱴᱷᱮᱱ ᱵᱟᱠᱤ ᱴᱟᱠᱟ ᱫᱚ ᱢᱩᱪᱟᱹᱫ 3 ᱯᱩᱨᱟᱹ ᱪᱟᱸᱫᱚ ᱨᱮᱭᱟᱜ ᱫᱤᱱ ᱟᱠᱷᱨᱤᱧ ᱛᱮ ᱦᱟᱹᱴᱤᱧ᱾ 30 ᱫᱤᱱ ᱥᱮ ᱠᱚᱢ 100, 90 ᱫᱤᱱ ᱥᱮ ᱵᱟᱹᱲᱛᱤ 0᱾",
  "hm.h.margin": "ᱢᱟᱨᱡᱤᱱ",
  "hm.h.margin.how": "ᱢᱩᱪᱟᱹᱫ 3 ᱪᱟᱸᱫᱚ ᱨᱮ ᱡᱷᱚᱛᱚ 100 ᱟᱠᱷᱨᱤᱧ ᱠᱷᱚᱱ ᱠᱤᱨᱤᱧ ᱟᱨ ᱠᱷᱚᱨᱚᱪ ᱛᱟᱭᱚᱢ {p} ᱵᱟᱧᱪᱟᱣ ᱮᱱᱟ᱾ ᱚᱱᱟ ᱞᱟᱦᱟ ᱨᱮᱭᱟᱜ 3 ᱪᱟᱸᱫᱚ: {q}᱾",
  "hm.h.margin.how1": "ᱢᱩᱪᱟᱹᱫ 3 ᱪᱟᱸᱫᱚ ᱨᱮ ᱡᱷᱚᱛᱚ 100 ᱟᱠᱷᱨᱤᱧ ᱠᱷᱚᱱ ᱠᱤᱨᱤᱧ ᱟᱨ ᱠᱷᱚᱨᱚᱪ ᱛᱟᱭᱚᱢ {p} ᱵᱟᱧᱪᱟᱣ ᱮᱱᱟ᱾",
  "hm.h.margin.good": "ᱴᱷᱤᱠ ᱦᱟᱹᱴᱤᱧ ᱵᱟᱧᱪᱟᱣᱜᱼᱟ᱾ ᱫᱟᱢ ᱵᱚᱫᱚᱞ ᱚᱠᱛᱚ ᱨᱩᱠᱷᱤᱭᱟᱹ ᱢᱮ᱾",
  "hm.h.margin.ok": "ᱢᱟᱨᱡᱤᱱ ᱠᱚᱢ ᱥᱮ ᱠᱚᱢᱚᱜ ᱠᱟᱱᱟ᱾ ᱟᱢᱟᱜ ᱟᱠᱷᱨᱤᱧ ᱫᱟᱢ ᱟᱨ ᱢᱩᱬᱩᱛ ᱟᱭᱴᱮᱢ ᱨᱮᱭᱟᱜ ᱠᱤᱨᱤᱧ ᱫᱟᱢ ᱧᱮᱞ ᱢᱮ᱾",
  "hm.h.margin.low": "ᱯᱟᱥᱤ ᱪᱮᱫ ᱦᱚᱸ ᱵᱟᱝ ᱵᱟᱧᱪᱟᱣᱜᱼᱟ᱾ ᱫᱟᱢ ᱵᱟᱹᱲᱛᱤ ᱢᱮ, ᱠᱷᱚᱨᱚᱪ ᱠᱚᱢ ᱢᱮ ᱥᱮ ᱦᱟᱹᱱᱤ ᱟᱭᱴᱮᱢ ᱟᱠᱷᱨᱤᱧ ᱵᱚᱸᱫ ᱢᱮ᱾",
  "hm.h.margin.rule": "ᱢᱩᱪᱟᱹᱫ 3 ᱯᱩᱨᱟᱹ ᱪᱟᱸᱫᱚ ᱨᱮᱭᱟᱜ ᱟᱠᱷᱨᱤᱧ ᱠᱷᱚᱱ ᱠᱤᱨᱤᱧ ᱟᱨ ᱠᱷᱚᱨᱚᱪ ᱠᱟᱴᱟᱣ, ᱟᱠᱷᱨᱤᱧ ᱨᱮᱭᱟᱜ ᱦᱟᱹᱴᱤᱧ ᱞᱮᱠᱟ᱾ 15 ᱥᱮ ᱵᱟᱹᱲᱛᱤ 100, 0 ᱥᱮ ᱠᱚᱢ 0; ᱞᱟᱦᱟ ᱨᱮᱭᱟᱜ 3 ᱪᱟᱸᱫᱚ ᱠᱷᱚᱱ 5 ᱯᱚᱭᱮᱱᱴ ᱠᱷᱚᱱ ᱵᱟᱹᱲᱛᱤ ᱠᱚᱢ ᱠᱷᱟᱱ 20 ᱯᱚᱭᱮᱱᱴ ᱠᱟᱴᱟᱣᱜᱼᱟ᱾ ᱛᱤ ᱨᱮᱭᱟᱜ ᱥᱴᱚᱠ ᱵᱟᱝ ᱞᱮᱠᱷᱟᱭᱚᱜᱼᱟ᱾",
  "hm.h.creep": "ᱠᱷᱚᱨᱚᱪ ᱵᱟᱹᱲᱛᱤ",
  "hm.h.creep.how": "ᱢᱩᱪᱟᱹᱫ ᱪᱟᱸᱫᱚ ᱟᱢᱟᱜ ᱠᱷᱚᱨᱚᱪ {l} ᱛᱟᱦᱮᱸ ᱠᱟᱱᱟ; ᱚᱱᱟ ᱞᱟᱦᱟ ᱨᱮᱭᱟᱜ 3 ᱪᱟᱸᱫᱚ ᱮᱵᱷᱟᱨᱮᱡ {a}᱾ ᱱᱚᱶᱟ ᱫᱚ {p}% ᱵᱚᱫᱚᱞ ᱠᱟᱱᱟ᱾",
  "hm.h.creep.good": "ᱠᱷᱚᱨᱚᱪ ᱛᱷᱤᱨ ᱢᱮᱱᱟᱜᱼᱟ᱾",
  "hm.h.creep.ok": "ᱠᱷᱚᱨᱚᱪ ᱵᱟᱹᱲᱛᱤᱜ ᱠᱟᱱᱟ᱾ ᱨᱤᱯᱚᱨᱴ ᱥᱠᱨᱤᱱ ᱨᱮ ᱚᱠᱟ ᱦᱮᱰ ᱵᱟᱹᱲᱛᱤ ᱮᱱᱟ ᱧᱮᱞ ᱢᱮ᱾",
  "hm.h.creep.low": "ᱠᱷᱚᱨᱚᱪ ᱟᱹᱰᱤ ᱵᱟᱹᱲᱛᱤ ᱮᱱᱟ᱾ ᱵᱟᱹᱲᱛᱤ ᱦᱮᱰ ᱯᱟᱱᱛᱮ ᱢᱮ, ᱟᱨ ᱢᱤᱫ ᱫᱷᱟᱣ ᱵᱤᱞ ᱵᱟᱝ ᱠᱟᱱ ᱧᱮᱞ ᱢᱮ᱾",
  "hm.h.creep.rule": "ᱢᱩᱪᱟᱹᱫ ᱯᱩᱨᱟᱹ ᱪᱟᱸᱫᱚ ᱨᱮᱭᱟᱜ ᱠᱷᱚᱨᱚᱪ ᱚᱱᱟ ᱞᱟᱦᱟ ᱨᱮᱭᱟᱜ 3 ᱪᱟᱸᱫᱚ ᱮᱵᱷᱟᱨᱮᱡ ᱥᱟᱶ᱾ 5% ᱥᱮ ᱠᱚᱢ ᱵᱟᱹᱲᱛᱤ 100, 40% ᱥᱮ ᱵᱟᱹᱲᱛᱤ 0᱾ ᱢᱤᱫ ᱫᱷᱟᱣ ᱢᱟᱨᱟᱝ ᱵᱤᱞ ᱢᱤᱫ ᱪᱟᱸᱫᱚ ᱞᱟᱹᱜᱤᱫ ᱠᱚᱢ ᱮ ᱦᱩᱭᱩᱜᱼᱟ᱾",
  "hm.rm.t": "ᱱᱚᱶᱟ ᱰᱤᱵᱷᱟᱭᱤᱥ ᱨᱮ ᱩᱭᱦᱟᱹᱨ",
  "hm.rm.p": "ᱮᱯ ᱡᱷᱤᱡ ᱚᱠᱛᱚ ᱛᱮᱦᱮᱧ ᱪᱮᱫ ᱞᱟᱹᱠᱛᱤ ᱚᱱᱟ ᱩᱫᱩᱜᱟ᱾ ᱡᱟᱞᱫᱤ ᱞᱟᱭᱤᱱ ᱞᱟᱹᱜᱤᱫ ᱫᱤᱱ ᱨᱮ ᱢᱤᱫ ᱫᱷᱟᱣ ᱯᱷᱚᱱ ᱱᱚᱴᱤᱯᱷᱤᱠᱮᱥᱚᱱ ᱦᱚᱸ ᱩᱫᱩᱜ ᱫᱟᱲᱮᱭᱟᱜᱼᱟ᱾",
  "hm.rm.on": "ᱮᱯ ᱡᱷᱤᱡ ᱚᱠᱛᱚ ᱱᱚᱴᱤᱯᱷᱤᱠᱮᱥᱚᱱ ᱩᱫᱩᱜ ᱢᱮ",
  "hm.rm.nosupport": "ᱱᱚᱶᱟ ᱵᱨᱟᱣᱡᱟᱨ ᱨᱮ ᱱᱚᱴᱤᱯᱷᱤᱠᱮᱥᱚᱱ ᱵᱟᱝ ᱪᱟᱞᱟᱜᱼᱟ᱾ ᱤᱧᱟᱜ ᱫᱤᱱ ᱨᱮᱭᱟᱜ ᱞᱤᱥᱴ ᱫᱚ ᱪᱟᱞᱟᱜᱼᱟ᱾",
  "hm.rm.denied": "ᱱᱚᱶᱟ ᱥᱟᱭᱤᱴ ᱞᱟᱹᱜᱤᱫ ᱱᱚᱴᱤᱯᱷᱤᱠᱮᱥᱚᱱ ᱵᱚᱸᱫ ᱢᱮᱱᱟᱜᱼᱟ᱾ ᱵᱨᱟᱣᱡᱟᱨ ᱨᱮᱭᱟᱜ ᱥᱟᱭᱤᱴ ᱥᱮᱴᱤᱝ ᱨᱮ ᱮᱢ ᱠᱟᱛᱮ ᱵᱚᱠᱥᱚ ᱫᱩᱦᱲᱟᱹ ᱴᱤᱠ ᱢᱮ᱾",
  "hm.rm.off": "ᱱᱚᱴᱤᱯᱷᱤᱠᱮᱥᱚᱱ ᱵᱚᱸᱫ ᱢᱮᱱᱟᱜᱼᱟ᱾",
  "hm.rm.set": "ᱱᱚᱴᱤᱯᱷᱤᱠᱮᱥᱚᱱ ᱪᱟᱹᱞᱩ ᱢᱮᱱᱟᱜᱼᱟ᱾ ᱮᱯ ᱡᱷᱤᱡ ᱚᱠᱛᱚ ᱡᱟᱞᱫᱤ ᱞᱟᱭᱤᱱ ᱧᱮᱞᱚᱜᱼᱟ᱾",
  "hm.rm.title": "{b}: ᱛᱮᱦᱮᱧ ᱟᱢᱟᱜ ᱞᱟᱹᱠᱛᱤ",
  "hm.rm.ics": "ᱵᱟᱠᱤ ᱛᱟᱨᱤᱠ ᱟᱢᱟᱜ ᱯᱷᱚᱱ ᱠᱮᱞᱮᱱᱰᱚᱨ ᱨᱮ ᱫᱚᱦᱚᱭ ᱢᱮ",
  "hm.rm.icsp": "ᱤᱫᱟᱹᱤ 60 ᱫᱤᱱ ᱨᱮᱭᱟᱜ ᱠᱮᱞᱮᱱᱰᱚᱨ ᱯᱷᱟᱭᱤᱞ ᱛᱮᱭᱟᱨᱚᱜᱼᱟ: ᱵᱤᱞ ᱵᱟᱠᱤ ᱛᱟᱨᱤᱠ ᱟᱨ ᱴᱮᱠᱥ ᱛᱟᱨᱤᱠ᱾ ᱟᱢᱟᱜ ᱠᱮᱞᱮᱱᱰᱚᱨ ᱨᱮ ᱥᱮᱞᱮᱫ ᱞᱟᱹᱜᱤᱫ ᱯᱷᱚᱱ ᱨᱮ ᱡᱷᱤᱡ ᱢᱮ, ᱚᱱᱟ ᱫᱚ ᱢᱤᱫ ᱫᱤᱱ ᱞᱟᱦᱟ ᱟᱡ ᱛᱮ ᱵᱟᱡᱟᱣᱜᱼᱟ, ᱮᱯ ᱵᱚᱸᱫ ᱛᱟᱦᱮᱸ ᱠᱷᱟᱱ ᱦᱚᱸ᱾",
  "hm.rm.icsgo": "ᱠᱮᱞᱮᱱᱰᱚᱨ ᱯᱷᱟᱭᱤᱞ ᱛᱮᱭᱟᱨ ᱢᱮ",
  "hm.rm.icsnone": "ᱤᱫᱟᱹᱤ 60 ᱫᱤᱱ ᱨᱮ ᱠᱮᱞᱮᱱᱰᱚᱨ ᱞᱟᱹᱜᱤᱫ ᱪᱮᱫ ᱦᱚᱸ ᱵᱟᱠᱤ ᱛᱟᱨᱤᱠ ᱵᱟᱹᱱᱩᱜᱼᱟ᱾",
  "hm.rm.icsdone": "{n} ᱛᱟᱨᱤᱠ ᱥᱟᱶ ᱠᱮᱞᱮᱱᱰᱚᱨ ᱯᱷᱟᱭᱤᱞ ᱛᱮᱭᱟᱨ ᱮᱱᱟ᱾ ᱥᱮᱞᱮᱫ ᱞᱟᱹᱜᱤᱫ ᱡᱷᱤᱡ ᱢᱮ᱾",
  "hm.rm.recv": "ᱦᱟᱛᱟᱣ ᱢᱮ",
  "hm.rm.pay": "ᱮᱢ ᱢᱮ",
  "hm.rm.lim": "ᱵᱨᱟᱣᱡᱟᱨ ᱪᱮᱫ ᱵᱟᱝ ᱫᱟᱲᱮᱭᱟᱜᱼᱟ",
  "hm.rm.l1": "ᱣᱮᱵ ᱥᱟᱦᱴᱟ ᱵᱚᱸᱫ ᱠᱷᱟᱱ ᱵᱟᱝ ᱪᱟᱞᱟᱜᱼᱟ, ᱟᱨ ᱱᱚᱶᱟ ᱮᱯ ᱛᱟᱭᱚᱢ ᱯᱩᱥ ᱢᱮᱥᱮᱡᱽ ᱠᱩᱞ ᱞᱟᱹᱜᱤᱫ ᱥᱟᱨᱵᱷᱟᱨ ᱵᱟᱹᱱᱩᱜᱼᱟ᱾ ᱚᱱᱟᱛᱮ ᱮᱯ ᱠᱷᱚᱱ ᱩᱭᱦᱟᱹᱨ ᱮᱠᱮᱱ ᱮᱯ ᱡᱷᱤᱡ ᱠᱷᱟᱱ ᱧᱮᱞᱚᱜᱼᱟ᱾",
  "hm.rm.l2": "ᱡᱚᱛᱚ ᱟᱢᱟᱜ ᱰᱤᱵᱷᱟᱭᱤᱥ ᱨᱮ ᱦᱤᱥᱟᱵᱚᱜᱼᱟ, ᱚᱱᱟᱛᱮ ᱤᱱᱴᱚᱨᱱᱮᱴ ᱵᱤᱱᱟ ᱦᱚᱸ ᱪᱟᱞᱟᱜᱼᱟ᱾ ᱟᱢᱟᱜ ᱵᱤᱡᱱᱮᱥ ᱵᱟᱵᱚᱛ ᱪᱮᱫ ᱦᱚᱸ ᱚᱠᱟᱨᱮ ᱦᱚᱸ ᱵᱟᱝ ᱠᱩᱞᱚᱜᱼᱟ᱾",
  "hm.rm.l3": "ᱵᱟᱝ ᱟᱫ ᱞᱟᱹᱠᱛᱤ ᱛᱟᱨᱤᱠ ᱞᱟᱹᱜᱤᱫ ᱠᱮᱞᱮᱱᱰᱚᱨ ᱯᱷᱟᱭᱤᱞ ᱵᱮᱵᱷᱟᱨ ᱢᱮ: ᱟᱢᱟᱜ ᱯᱷᱚᱱ ᱠᱮᱞᱮᱱᱰᱚᱨ ᱟᱡ ᱛᱮ ᱵᱟᱡᱟᱣᱜᱼᱟ᱾ ᱱᱚᱶᱟ ᱫᱚ ᱛᱮᱦᱮᱧ ᱨᱮᱭᱟᱜ ᱪᱤᱛᱟᱹᱨ ᱠᱟᱱᱟ, ᱚᱱᱟᱛᱮ ᱱᱟᱶᱟ ᱵᱤᱞ ᱚᱞ ᱛᱟᱭᱚᱢ ᱱᱟᱶᱟ ᱯᱷᱟᱭᱤᱞ ᱛᱮᱭᱟᱨ ᱢᱮ᱾",
