  "cp.ewb_p": "An e-way bill is needed to move goods when the consignment value is above {l} (Rule 138(1) of the CGST Rules). It is worked out for each consignment, not for the year. Bills where every line has a service code (SAC, starting 99) are not counted; bills with no code are counted, so check them.",
  "cp.ewb_n": "Sales bills this year above that value: {n} (the largest is {m}). Goods moved on them may need an e-way bill; services do not.",
